<?php
namespace App\Services\Licensing\Kslp;
use DomainException;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class KslpIssuerSubscriptionAuthority{
 public const TIERS=["professional","business","enterprise","custom_oem"];
 public function subscribe(string $organizationId,string $tier,int $productLimit,int $monthlyIssueLimit,?\DateTimeInterface $periodEnd=null):array{if(!in_array($tier,self::TIERS,true))throw new DomainException("KSLP_INVALID_ISSUER_TIER");if($productLimit<1||$monthlyIssueLimit<1)throw new DomainException("KSLP_ISSUER_POLICY_NOT_CONFIGURED");$products=$productLimit;$issues=$monthlyIssueLimit;$now=now();DB::table("kslp_issuer_subscriptions")->updateOrInsert(["organization_id"=>$organizationId],["id"=>(string)Str::uuid(),"tier"=>$tier,"status"=>"active","product_limit"=>$products,"monthly_issue_limit"=>$issues,"current_period_end"=>$periodEnd,"created_at"=>$now,"updated_at"=>$now]);return (array)DB::table("kslp_issuer_subscriptions")->where("organization_id",$organizationId)->first();}
 public function registerProduct(string $organizationId,string $code,string $name,array $features=[],array $limits=[]):array{$sub=$this->requireActive($organizationId);$count=DB::table("kslp_licensed_products")->where("organization_id",$organizationId)->count();if($count>=(int)$sub->product_limit)throw new DomainException("KSLP_ISSUER_PRODUCT_LIMIT");if(!preg_match("/^[A-Z0-9][A-Z0-9_.:-]{2,95}$/",$code))throw new DomainException("KSLP_INVALID_PRODUCT_CODE");$id=(string)Str::uuid();DB::table("kslp_licensed_products")->insert(["id"=>$id,"organization_id"=>$organizationId,"product_code"=>$code,"name"=>$name,"status"=>"active","default_features"=>json_encode($features),"default_limits"=>json_encode($limits),"created_at"=>now(),"updated_at"=>now()]);return (array)DB::table("kslp_licensed_products")->where("id",$id)->first();}
 public function authorizeIssue(string $organizationId,string $productCode):array{$this->requireActive($organizationId);$p=DB::table("kslp_licensed_products")->where("organization_id",$organizationId)->where("product_code",$productCode)->where("status","active")->first();if(!$p)throw new DomainException("KSLP_ISSUER_PRODUCT_NOT_AUTHORIZED");return (array)$p;}
 private function requireActive(string $organizationId):object{$s=DB::table("kslp_issuer_subscriptions")->where("organization_id",$organizationId)->where("status","active")->first();if(!$s)throw new DomainException("KSLP_ISSUER_SUBSCRIPTION_REQUIRED");if($s->current_period_end&&now()->gt($s->current_period_end))throw new DomainException("KSLP_ISSUER_SUBSCRIPTION_EXPIRED");return $s;}
}
